using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class Layer {
 public long VisualVersion;readonly Queue<KeyValuePair<long,Rectangle>> visualChanges=new Queue<KeyValuePair<long,Rectangle>>();
 public void MarkVisual(Rectangle area){VisualVersion++;visualChanges.Enqueue(new KeyValuePair<long,Rectangle>(VisualVersion,area));while(visualChanges.Count>64)visualChanges.Dequeue();}
 public Rectangle ChangesSince(long version){var full=new Rectangle(0,0,Image.Width,Image.Height);if(version<0||visualChanges.Count==0||version<visualChanges.Peek().Key-1)return full;Rectangle result=Rectangle.Empty;foreach(var change in visualChanges)if(change.Key>version){if(change.Value.IsEmpty)return full;result=result.IsEmpty?change.Value:Rectangle.Union(result,change.Value);}return result;}
}
class LayerScreen:IDisposable {public Bitmap Image;public long Version=-1,Used;public LayerScreen(Size size){Image=new Bitmap(size.Width,size.Height,PixelFormat.Format32bppPArgb);}public void Dispose(){Image.Dispose();}}
partial class Canvas {
 readonly Dictionary<Layer,LayerScreen> screenLayers=new Dictionary<Layer,LayerScreen>();Document screenDocument;Size screenSize;float screenZoom,screenAngle;PointF screenOffset;long screenUse;
 void ClearScreenLayers(){foreach(var value in screenLayers.Values)value.Dispose();screenLayers.Clear();}
 protected override void Dispose(bool disposing){if(disposing){ClearScreenLayers();DisposeNavigation();}base.Dispose(disposing);}
 void PaintCachedDocument(Graphics target,Layer previewLayer=null,Bitmap preview=null){if(ClientSize.Width<1||ClientSize.Height<1){Doc.Paint(target);return;}if(screenDocument!=Doc||screenSize!=ClientSize||screenZoom!=Zoom||screenOffset!=Offset||screenAngle!=ViewAngle){ClearScreenLayers();screenDocument=Doc;screenSize=ClientSize;screenZoom=Zoom;screenOffset=Offset;screenAngle=ViewAngle;}foreach(var removed in screenLayers.Keys.Where(l=>!Doc.Layers.Contains(l)||!l.Visible).ToArray()){screenLayers[removed].Dispose();screenLayers.Remove(removed);}var state=target.Save();target.ResetTransform();var canvasRect=new RectangleF(Offset.X,Offset.Y,Doc.Width*Zoom,Doc.Height*Zoom);using(var page=new GraphicsPath()){page.AddPolygon(new[]{RotateView(new PointF(canvasRect.Left,canvasRect.Top)),RotateView(new PointF(canvasRect.Right,canvasRect.Top)),RotateView(new PointF(canvasRect.Right,canvasRect.Bottom)),RotateView(new PointF(canvasRect.Left,canvasRect.Bottom))});target.SetClip(page,CombineMode.Intersect);target.FillPath(Brushes.White,page);}foreach(var layer in Doc.Layers){if(!layer.Visible||layer.Opacity<=0||layer.PermanentlyLocked)continue;if(layer==previewLayer&&preview!=null){using(var attrs=new ImageAttributes()){var matrix=new ColorMatrix();matrix.Matrix33=layer.Opacity;attrs.SetColorMatrix(matrix);var previewState=target.Save();ApplyViewRotation(target);target.DrawImage(preview,Rectangle.Round(canvasRect),0,0,preview.Width,preview.Height,GraphicsUnit.Pixel,attrs);target.Restore(previewState);}continue;}LayerScreen cached;if(!screenLayers.TryGetValue(layer,out cached)){int limit=Math.Max(2,(int)(96L*1024*1024/Math.Max(1,(long)ClientSize.Width*ClientSize.Height*4)));if(screenLayers.Count>=limit){var oldest=screenLayers.OrderBy(k=>k.Value.Used).First();oldest.Value.Dispose();screenLayers.Remove(oldest.Key);}cached=new LayerScreen(ClientSize);screenLayers.Add(layer,cached);}cached.Used=++screenUse;if(cached.Version!=layer.VisualVersion){var dirty=layer.ChangesSince(cached.Version);Rectangle screen=RotatedScreenBounds(dirty);if(cached.Version<0)screen=ClientRectangle;if(screen.Width>0&&screen.Height>0)using(var g=Graphics.FromImage(cached.Image)){g.SetClip(screen);g.CompositingMode=CompositingMode.SourceCopy;g.FillRectangle(Brushes.Transparent,screen);ApplyViewRotation(g);g.TranslateTransform(Offset.X,Offset.Y);g.ScaleTransform(Zoom,Zoom);PaintViewLayer(g,layer);}cached.Version=layer.VisualVersion;}if(layer.Opacity>=1)target.DrawImageUnscaled(cached.Image,0,0);else using(var attrs=new ImageAttributes()){var matrix=new ColorMatrix();matrix.Matrix33=layer.Opacity;attrs.SetColorMatrix(matrix);target.DrawImage(cached.Image,ClientRectangle,0,0,ClientSize.Width,ClientSize.Height,GraphicsUnit.Pixel,attrs);}}target.Restore(state);}
 public void TestDisplayCache(){Size=new Size(600,400);Zoom=.4f;Offset=new PointF(10,10);using(var b=new Bitmap(600,400))using(var g=Graphics.FromImage(b)){PaintCachedDocument(g);var layer=Doc.Selected;long version=layer.VisualVersion;using(var draw=Graphics.FromImage(layer.Image))draw.FillRectangle(Brushes.Coral,100,100,40,40);layer.UpdatePixelAdjustment(new Rectangle(100,100,40,40));if(layer.VisualVersion==version)throw new Exception("Pixel display invalidation");PaintCachedDocument(g);using(var updated=(Bitmap)b.Clone()){ClearScreenLayers();PaintCachedDocument(g);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var a=updated.GetPixel(x,y);var z=b.GetPixel(x,y);if(Math.Abs(a.R-z.R)>1||Math.Abs(a.G-z.G)>1||Math.Abs(a.B-z.B)>1||a.A!=z.A)throw new Exception("Incremental display differs from full rebuild");}}layer.Opacity=.5f;PaintCachedDocument(g);layer.Visible=false;PaintCachedDocument(g);layer.Visible=true;PaintCachedDocument(g);SetZoom(.6f,new Point(150,150));PaintCachedDocument(g);if(screenZoom!=.6f)throw new Exception("View invalidation");}}
}
partial class Studio {
 public void TestVersion34(){SetDocument(new Document("A4",100),null);canvas.TestDisplayCache();AddTypedLayer(true);var layer=canvas.Doc.Selected;layer.Adjustment=new LayerAdjustment{Hue=60,Brightness=10};var shape=new VectorShape{Kind="Line",Width=10,Colour=Color.Red,Points=new List<PointF>{new PointF(100,100),new PointF(200,200)}};layer.Vectors.Add(shape);layer.Rendered();var before=shape.Bounds();shape.Points[1]=new PointF(250,180);layer.UpdateVectorRegion(RectangleF.Union(before,shape.Bounds()));var patch=Document.Png(layer.Rendered());layer.InvalidateVectors();if(!patch.SequenceEqual(Document.Png(layer.Rendered())))throw new Exception("Vector adjustment region equivalence");dirty=false;}
}
}
